// src/main.ts
async function main() {
	const action = parseCli(process.argv.slice(2));
	if (action.kind === "help") {
		process.stdout.write(helpText(SERVER_VERSION));
		return;
	}
	if (action.kind === "version") {
		process.stdout.write(`${SERVER_VERSION}\n`);
		return;
	}
	const config = readConfig(process.env);
	await createServer(new AgentClient(config), config.apiUrl).connect(new StdioServerTransport());
	process.stderr.write(`arkanva-mcp ${SERVER_VERSION} ready on stdio (${config.apiUrl})\n`);
}
main().catch((error) => {
	const message = error instanceof ConfigError || error instanceof UsageError ? error.message : String(error);
	process.stderr.write(`arkanva-mcp: ${message}\n`);
	process.exit(1);
});
export {};
